content.text:
The root cause is ts-seat-service, and its effect reaches users through travel, travel-plan and preserve.

```json
{
  "root_causes": [
    {
      "service": "ts-seat-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, ch.service_name callee, ch.span_name callee_span, count(*) n, approx_quantile(c.duration/1e6,0.5) client_p50, approx_quantile(ch.duration/1e6,0.5) child_p50 FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' GROUP BY 1,2,3 ORDER BY n DESC LIMIT 15",
          "claim": "Seat's POST to order-service /order/tickets takes ~2902ms client-side, while the order-service child span takes ~3.8ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) caller_client_p50_ms, approx_quantile(ch.duration/1e6,0.5) callee_server_p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND ch.attr_span_kind='Server' AND ch.service_name='ts-seat-service' GROUP BY 1,2 ORDER BY 1,2",
          "claim": "Seat's server latency is ~2.9s for callers travel, travel-plan and preserve, while travel2 calls to seat stay ~20ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.span_name, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) client_p50 FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-seat-service' AND c.attr_span_kind='Client' AND ch.service_name='ts-order-other-service' GROUP BY 1,2",
          "claim": "Seat's calls to ts-order-other-service stay fast (~9ms p50), so the delay is specific to the /order/tickets path."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' src, attr_source, attr_destination, sum(count) cnt, sum(sum)/nullif(sum(count),0) avg_s FROM abnormal_metrics_histogram WHERE metric='hubble_http_request_duration_seconds' AND attr_source LIKE '%ts-seat-service%' AND attr_destination LIKE '%ts-order-service%' GROUP BY 1,2,3",
          "claim": "Network-level HTTP duration seat→order-service averages ~8.6ms, so the seconds are added inside seat before the wire."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) caller_client_p50_ms, approx_quantile(ch.duration/1e6,0.5) callee_server_p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND ch.attr_span_kind='Server' AND c.service_name='ts-travel-service' AND ch.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Travel's client calls to seat take ~2917ms p50 and travel's trip/left server spans reach ~18s p95."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) caller_client_p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND ch.attr_span_kind='Server' AND c.service_name='ts-travel-plan-service' AND ch.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Travel-plan's client calls to seat take ~2913ms p50 in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) caller_client_p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND ch.attr_span_kind='Server' AND c.service_name='ts-preserve-service' AND ch.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Preserve's client calls to seat take ~2911ms p50 in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) caller_client_p50_ms, approx_quantile(ch.duration/1e6,0.5) callee_server_p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND ch.attr_span_kind='Server' AND c.service_name='ts-route-plan-service' AND ch.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "Route-plan's calls to travel-service are slower in the abnormal window, and its server spans reach ~18s p95."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(c.duration/1e6,0.5) caller_client_p50_ms, approx_quantile(ch.duration/1e6,0.5) callee_server_p50_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.attr_span_kind='Client' AND ch.attr_span_kind='Server' AND c.service_name='ts-travel-plan-service' AND ch.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan's calls to route-plan take ~1367ms p50, with route-plan server spans ~1321ms."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(ch.duration/1e6,0.95) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND c.attr_span_kind='Client' AND ch.service_name='ts-travel-plan-service' GROUP BY 1,2",
          "claim": "UI dashboard's calls into travel-plan slow to tens of seconds p95 in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(ch.duration/1e6,0.95) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND c.attr_span_kind='Client' AND ch.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "UI dashboard's calls into travel-service slow to ~18s p95 in the abnormal window."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name caller, ch.service_name callee, count(*) n, approx_quantile(ch.duration/1e6,0.95) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces ch ON ch.parent_span_id=c.span_id AND ch.trace_id=c.trace_id WHERE c.service_name='ts-ui-dashboard' AND c.attr_span_kind='Client' AND ch.service_name='ts-preserve-service' GROUP BY 1,2",
          "claim": "UI dashboard's calls into preserve-service slow to ~9.5s p95 in the abnormal window."
        }
      ]
    }
  ]
}
